import {beforeProgramBatch9AcceptanceRelease,beforeProgramBatch9AcceptanceManifest,beforeProgramBatch9AcceptanceSourceBytes,beforeProgramBatch9AcceptanceCases,beforeProgramBatch9AcceptanceConcepts} from "./question-program-batch9-acceptance-test-support";
// Preserve every authoring-era exclusion/pin against its exact verified epoch.
// Batch9 independently asserts current accepted and still-withheld tuples.
const live=beforeProgramBatch9AcceptanceRelease(batch9ActiveRelease);
import { createHash } from 'node:crypto';
