const salvageRead = (path: string) => salvageReadFile(new URL(path, salvageRoot), 'utf8');
const salvageHash = (value: unknown) => salvageCreateHash('sha256').update(typeof value === 'string' ? value : JSON.stringify(value)).digest('hex');
const salvageSourceCases = [...salvageLane.INTRAOP_I11_CASES];
const salvageSourceTimings = [...salvageLane.INTRAOP_I11_TIMING_ENTRIES];
const salvageSourceOrders = [...salvageLane.INTRAOP_I11_ORDER_PROPOSALS];

describe('Batch9 standalone salvage: anesthetic-intraoperative-crises', () => {
  it('preserves every original export, historical packet field and source/document preimage', () => {
    const expectedExports = ['INTRAOP_I11_SALVAGE', 'INTRAOP_I11_SALVAGE_CASES', 'INTRAOP_I11_SALVAGE_METADATA', 'INTRAOP_I11_SALVAGE_PREVIEW_RELEASE', 'INTRAOP_I11_SALVAGE_TIMING_ENTRIES'].sort();
    expect(Object.keys(salvageLane).filter(name => name.startsWith('INTRAOP_I11_SALVAGE')).sort()).toEqual(expectedExports);
    const originalExports = Object.fromEntries(Object.entries(salvageLane).sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0).filter(([name]) => !name.startsWith('INTRAOP_I11_SALVAGE')).map(([name, value]) => [name, (name === 'INTRAOP_I11_PACKET' ? Object.fromEntries(Object.entries(value as Record<string, unknown>).filter(([key]) => key !== 'salvage')) : value)]));
    expect(salvageHash(originalExports)).toBe(salvageDraft.preservation.originalExportsSha256);
    const originalPacket = JSON.parse(salvageRead('docs/research/question-intraop-anesthetic-intraoperative-crises-20261112.json')) as Record<string, unknown>;
    delete originalPacket.salvage;
    expect(salvageHash(originalPacket)).toBe(salvageDraft.preservation.originalPacketContentSha256);
    expect(salvageHash(salvageRead('packages/clinical-content/src/question-intraop-anesthetic-intraoperative-crises-20261112.ts').split(salvageDraft.preservation.sourceMarker)[0])).toBe(salvageDraft.preservation.originalSourceSha256);
    expect(salvageHash(salvageRead('docs/research/question-intraop-anesthetic-intraoperative-crises-20261112.md').split(salvageDraft.preservation.markdownMarker)[0])).toBe(salvageDraft.preservation.originalMarkdownSha256);
  });

  it('contains only each requested PASS decision with exact scored bytes and explicit final closure', () => {
    expect(salvageDraft.definitions.map(spec => spec.nodeId)).toEqual(["node.intraop.anesthetic-intraoperative-crises.anaphylaxis-infusion.v1"]);
    expect(salvageCases).toHaveLength(1);
    expect(salvageMetadata.questions).toEqual(salvageDraft.questions);
    expect(salvageMetadata.concepts).toEqual(salvageDraft.authoringConcepts);
    for (const spec of salvageDraft.definitions) {
      const prior = salvageSourceCases.find(value => value.id === spec.sourceCaseId && value.decisionNodes.some(node => node.id === spec.nodeId))!;
      const passed = prior.decisionNodes.find(node => node.id === spec.nodeId)!;
      const clinicalCase = salvageCases.find(value => value.id === spec.caseId)!;
      const node = clinicalCase.decisionNodes[0]!;
      expect(() => salvageCaseSchema.parse(clinicalCase)).not.toThrow();
      expect(clinicalCase.id).toBe(spec.sourceCaseId.replace(/\.v1$/, '-salvage.v1'));
      expect(clinicalCase.id).toMatch(/-salvage\.v1$/);
      expect(clinicalCase.decisionNodes).toHaveLength(1);
      expect(salvageHash(prior)).toBe(spec.sourceCaseSha256);
      expect(salvageHash(passed)).toBe(spec.sourceNodeSha256);
      expect(salvageHash(clinicalCase)).toBe(spec.salvageCaseSha256);
      expect(salvageHash(salvageLane.INTRAOP_I11_QUESTIONS.find(value => value.id === spec.questionVariantId))).toBe(spec.sourceQuestionSha256);
      expect(salvageHash(salvageLane.INTRAOP_I11_TESTED_CONCEPTS.find(value => value.id === spec.conceptId))).toBe(spec.sourceConceptSha256);
      expect(salvageHash(salvageLane.INTRAOP_I11_AUTHORING_CONCEPTS.find(value => value.id === spec.conceptId))).toBe(spec.sourceAuthoringConceptSha256);
      expect(spec.contextExhibitChanges).toEqual([]);
      const expectedNode = structuredClone(passed);
      for (const change of spec.contextExhibitChanges as Array<{ row: number; column: number; before: string; after: string }>) {
        if (expectedNode.exhibit?.kind !== 'table') throw new Error('Expected the preserved table context');
        expect(expectedNode.exhibit.cells[change.row]![change.column]).toBe(change.before);
        expectedNode.exhibit.cells[change.row]![change.column] = change.after;
      }
      expectedNode.terminalDispositions = node.terminalDispositions;
      expect(node).toMatchObject(expectedNode);
      expect(node.answerChoices).toEqual(passed.answerChoices);
      expect(node.stem).toBe(passed.stem); expect(node.explanation).toBe(passed.explanation);
      expect(node.shuffleAnswers).toBe(true); expect(node.resultGateAfter).toBeNull();
      expect(node.answerChoices.filter(value => value.isCorrect)).toHaveLength(1);
      expect(node.answerChoices.every(value => value.serviceRequest === null)).toBe(true);
      expect(node.terminalDispositions.map(value => value.answerChoiceId).sort()).toEqual(node.answerChoices.filter(value => !value.isCorrect).map(value => value.id).sort());
      expect(node.terminalDispositions.every(value => value.kind === 'no_terminal_outcome')).toBe(true);
      expect(clinicalCase.learningSummary).toBe(passed.explanation);
      expect(spec.blockedByNodeIds.some(id => clinicalCase.decisionNodes.some(value => value.id === id))).toBe(false);
      expect(salvageHash(salvageRead(spec.passReview.path))).toBe(spec.passReview.sha256);
      expect(spec.passReview.verdict).toBe('PASS');
    }
  });

  it('keeps the setting, family, patient and completed-fact context self-contained and unapproved', () => {
    expect(salvageDraft.reviewStatus).toBe('needs_clinician_review');
    expect(salvageDraft.managerAccepted).toBe(false); expect(salvageDraft.clinicalApproval).toBe(false);
    expect(salvagePreview.publicationStatus).toBe('synthetic_unapproved_prototype');
    expect(salvageDraft.cases).toEqual(salvageCases);
    for (const spec of salvageDraft.definitions) {
      const clinicalCase = salvageCases.find(value => value.id === spec.caseId)!;
      const prior = salvageSourceCases.find(value => value.id === spec.sourceCaseId && value.decisionNodes.some(node => node.id === spec.nodeId))!;
      expect(clinicalCase.prototypeDemographics).toEqual(prior.prototypeDemographics);
      expect(clinicalCase.patientDisplayName).toBe(prior.patientDisplayName);
      expect(clinicalCase.requiredClinicalSetting).toBe(prior.requiredClinicalSetting);
      expect(clinicalCase.requiredCapabilityIds).toEqual(prior.requiredCapabilityIds);
      expect(clinicalCase.earliestFacilityStage).toBe(prior.earliestFacilityStage);
      expect(clinicalCase.releasePointId).toBe(prior.releasePointId);
      expect(clinicalCase.routineEligible).toBe(false); expect(clinicalCase.tutorialEligible).toBe(false);
      expect(clinicalCase.approvedInstantiationProfiles).toHaveLength(1);
      const profile = clinicalCase.approvedInstantiationProfiles![0]!;
      expect(profile.id).toBe(spec.profileId);
      expect(profile.prototypeDemographics).toEqual(prior.approvedInstantiationProfiles![0]!.prototypeDemographics);
      expect(profile.presentation).toBe(clinicalCase.presentation);
      const sourceContext = salvageLane.INTRAOP_I11_PROCEDURE_CONTEXT_PROPOSALS.find(value => value.caseId === spec.sourceCaseId)!;
      expect(salvageHash(sourceContext)).toBe(spec.sourceProcedureContextSha256);
      const { salvageNodeId, salvagePhase, ...context } = salvageDraft.procedureContextProposals.find(value => value.caseId === spec.caseId)!;
      expect({ ...context, caseId: spec.sourceCaseId }).toEqual(sourceContext);
      expect(salvageNodeId).toBe(spec.nodeId); expect(salvagePhase).toContain("completed observations");
      const review = salvageDraft.caseReviews.find(value => value.caseId === spec.caseId)!;
      expect(review.reviewStatus).toBe('needs_clinician_review');
      expect(review.profileReviewStatus).toBe('needs_clinician_review');
      expect(review.educationalTier).toBeTypeOf("number"); expect(review.acuity).toBeTruthy();
      expect(spec.evidenceClaimIds.length).toBeGreaterThan(0);
      for (const id of spec.evidenceClaimIds) expect(salvageMetadata.claims.some(value => value.id === id)).toBe(true);
      for (const id of spec.sourceIds) expect(salvageMetadata.sources.some(value => value.id === id)).toBe(true);
      expect(salvageDraft.familyContexts).toEqual([]);
    }
  });

  it('retains every exact choice-timing and unexecuted order mapping under the salvage case ID', () => {
    expect(salvageLane.INTRAOP_I11_SALVAGE_TIMING_ENTRIES).toHaveLength(salvageCases.length);
    for (const spec of salvageDraft.definitions) {
      const source = salvageSourceTimings.find(value => value.caseId === spec.sourceCaseId && value.nodeId === spec.nodeId)!;
      const timing = salvageLane.INTRAOP_I11_SALVAGE_TIMING_ENTRIES.find(value => value.caseId === spec.caseId)!;
      expect({ ...timing, caseId: spec.sourceCaseId }).toEqual(source);
      if (timing.classification.kind === "test_choices") {
        const node = salvageCases.find(value => value.id === spec.caseId)!.decisionNodes[0]!;
        expect(timing.classification.choices.map(value => [value.choiceId, value.choiceLabel])).toEqual(node.answerChoices.map(value => [value.id, value.label]));
      }
      for (const proposal of (salvageDraft.orderProposals as Array<{ caseId: string; [key: string]: unknown }>).filter(value => value.caseId === spec.caseId)) {
        expect(salvageSourceOrders.some(value => salvageHash(value) === salvageHash({ ...proposal, caseId: spec.sourceCaseId }))).toBe(true);
      }
    }
  });

  it('runs the full cue scanner on every canonical and finite-profile salvage context with zero findings', async () => {
    const { collectAuthoredMetadata, inventoryRelease } = await import(new URL('tools/question-quality/bank.mjs', salvageRoot).href);
    const report = inventoryRelease(salvagePreview, collectAuthoredMetadata(salvageMetadata));
    expect(report.totals).toEqual(salvageDraft.cueLint.totals);
    expect(report.totals).toMatchObject({ cases: 1, uniqueVariants: 1, profileContexts: 2, findings: 0, variantsWithFindings: 0, missingAuthoredVersion: 0, missingEducationalTier: 0, variantsWithCompleteRationales: 1 });
    expect(report.variants.flatMap((value: { findings: unknown[] }) => value.findings)).toEqual([]);
    expect(salvageDraft.cueLint.suppressions).toEqual([]);
  });
});
// END BATCH9 STANDALONE SALVAGE 20261113
